import {verifiedFetch} from '@github-ui/verified-fetch'
import {useQuery} from '@github-ui/react-query'
import {secretScanningAIAutofixSuggestionPath} from '../../../../paths'
import type {Repository} from '../../../../types/repo-types'
import type {Alert} from '../../../../types/alert-types'
import {UnifiedDiffLines} from '@github-ui/diffs/DiffParts'
import {Header, type SxProp, sx} from '@primer/react'
import type {RepoBlobLocation} from '../../../../types/location-types'
import styled from 'styled-components'
import {SkeletonText} from '@primer/react/experimental'
import {AIRemediationFeedback} from './components/AIRemediationFeedback'
import {getLineNumberWidth} from '@github-ui/diffs/diff-line-helpers'

const StyledDiffContainer = styled.div<SxProp>`
  .hunk-kebab-icon {
    margin-left: var(--base-size-16);
  }

  [class*='diffTextMarker'] {
    display: none;
  }

  ${sx}
`

export function AutofixAISuggestion({
  repository,
  alert,
  firstLocation,
}: {
  repository: Repository
  alert: Alert
  firstLocation: RepoBlobLocation | undefined
}) {
  const autofixPath = secretScanningAIAutofixSuggestionPath(
    repository.owner_display_login,
    repository.name,
    alert.number,
  )

  const {
    isLoading: isAutofixLoading,
    data: {
      diff_lines: diffLines = [],
      explanation: autofixExplanation = '',
      accept_feedback: acceptFeedback = false,
    } = {},
  } = useQuery({
    queryKey: ['secret-scanning', autofixPath],
    staleTime: Infinity,
    queryFn: async () => {
      const fallback = {
        explanation: 'Consider opening a pull request with a code change to remove this secret from your codebase.',
        diff_lines: [],
        accept_feedback: false,
      }
      try {
        const result = await verifiedFetch(autofixPath, {
          method: 'get',
        })
        if (!result.ok) {
          return fallback
        }
        const res = await result.json()
        return {
          diff_lines: res.diff_lines,
          explanation: res.explanation,
          accept_feedback: res.accept_feedback,
        }
      } catch {
        return fallback
      }
    },
  })

  return (
    <>
      <div className="pl-3 pr-3 pb-3">
        <p className="f5 text-semibold pt-2 mb-2">How do I rotate the secret?</p>
        {isAutofixLoading ? <SkeletonText lines={2} /> : <p>{autofixExplanation}</p>}
      </div>
      {diffLines.length > 0 && (
        <div className="pl-3 pr-3 pb-3">
          <Header
            className="border rounded-top-2 bgColor-inset p-1 d-flex bgColor-inset p-0"
            data-testid={'toggle-location'}
          >
            <span className="text-mono ml-2 p-1 fgColor-default text-small">{firstLocation?.path}</span>
          </Header>
          <StyledDiffContainer data-testid="secret-scanning-autofix-diff">
            <UnifiedDiffLines
              lines={diffLines ?? []}
              tabSize={0}
              lineWidth={getLineNumberWidth(diffLines)}
              sx={{borderLeft: 1, borderRight: 1, borderBottom: 0}}
            />
          </StyledDiffContainer>
          <div className="rounded-bottom-2 border border-sm-top-0 border-md-top-0 border-lg-top-0 border-xl-top-0 p-1" />
        </div>
      )}
      <div className="pl-3 pr-3 pb-3">{acceptFeedback && <AIRemediationFeedback stepName="autofix" />}</div>
      <div className="pl-3 pr-3 pb-3">
        <p className="f5 text-semibold mb-2">How do I securely store the secret?</p>
        <p>
          To securely store a secret in GitHub Actions, go to your repository&apos;s &#34;Settings&#34; tab, select
          &#34;Secrets&#34; under &#34;Actions&#34;, and click &#34;New repository secret&#34;. Enter the secret&apos;s
          name and value, and then click &#34;Add secret&#34;. Use the secret in workflows with `$&#123;&#123;
          secrets.&lt;SECRET_NAME&gt; &#125;&#125;`, where SECRET_NAME is the name you chose when you created the
          secret. Never hardcode sensitive data in workflow files.
        </p>

        <p className="f5 text-semibold mb-2">
          What are some additional considerations to make before closing the alert?
        </p>
        <p>
          To ensure complete remediation of the secret leak, you should review logs for potential abuse of the secret
          and verify endpoints relying on the secret are fully functioning.
        </p>
      </div>
    </>
  )
}

try{ AutofixAISuggestion.displayName ||= 'AutofixAISuggestion' } catch {}