import {AnchoredOverlay, ActionList, Box, Button, RadioGroup, FormControl, Radio, Text, Textarea} from '@primer/react'
import {Octicon} from '@primer/react/deprecated'
import {useRef, useState} from 'react'
import type {Repository} from '../../types/repo-types'

import {verifiedFetch} from '@github-ui/verified-fetch'
import {ResolutionType} from '../../types/alert-types'
import {secretScanningTokenCreateClosureRequestsPath} from '../../paths'
import {useNavigate} from '@github-ui/use-navigate'
import {TriangleDownIcon} from '@primer/octicons-react'
import {useErrorContext} from '../shared/ErrorContext'

export function AlertClosureRequest({
  repository,
  alertNumber,
  redirectUrl,
  onDismiss,
  alignEnd,
}: {
  repository: Repository
  alertNumber: number
  redirectUrl: string
  onDismiss?: () => void
  alignEnd?: boolean
}) {
  const navigate = useNavigate()
  const errorContext = useErrorContext()
  const [selectedCloseReason, setSelectedClosureRequestReason] = useState('')
  const [shouldShowCloseAlertForm, setShouldShowCloseAlertForm] = useState(false)

  const closureRequestCommentTextArea = useRef<HTMLTextAreaElement>(null)
  const anchorRef = useRef(null)

  const resolveURL = secretScanningTokenCreateClosureRequestsPath(repository.owner_display_login, repository.name)
  function handleRadioGroupChange(value: string | null) {
    setSelectedClosureRequestReason(value ?? '')
  }
  const [reasonValidationError, setReasonValidationError] = useState(false)
  const [commentValidationError, setCommentValidationError] = useState(false)

  function hideActionsMenu() {
    setSelectedClosureRequestReason('')
    setShouldShowCloseAlertForm(false)
  }

  async function handleSubmit() {
    if (!closureRequestCommentTextArea?.current?.value || !selectedCloseReason) {
      if (!closureRequestCommentTextArea?.current?.value) {
        setCommentValidationError(true)
      } else {
        setCommentValidationError(false)
      }
      if (!selectedCloseReason) {
        setReasonValidationError(true)
      } else {
        setReasonValidationError(false)
      }
    } else {
      const formData = {
        id: alertNumber,
        resolution: selectedCloseReason || ResolutionType.Reopened,
        closure_request_comment: closureRequestCommentTextArea?.current?.value ?? '',
        repository: repository.name,
        user_id: repository.owner_display_login,
      }

      const result = await verifiedFetch(resolveURL, {
        headers: {
          Accept: 'application/json',
          'Content-Type': 'application/json',
        },
        method: 'post',
        body: JSON.stringify(formData),
      })

      hideActionsMenu()
      navigate(redirectUrl)

      if (!result.ok) {
        const errorText = await result.text()
        errorContext.showError(errorText)
      }

      // call the callback if it exists
      onDismiss?.()
    }
  }
  const revokeText = 'This secret has been revoked'
  const usedInTestsText = 'This secret is not in production code'
  const falsePositiveText = 'This alert is not valid'
  const wontFixText = 'This alert is not relevant'

  return (
    <>
      <Button ref={anchorRef} onClick={() => setShouldShowCloseAlertForm(true)}>
        Dismiss alert
        <Octicon icon={TriangleDownIcon} />
      </Button>

      <AnchoredOverlay
        anchorRef={anchorRef}
        renderAnchor={null}
        open={shouldShowCloseAlertForm}
        onOpen={() => setShouldShowCloseAlertForm(true)}
        onClose={hideActionsMenu}
        focusZoneSettings={{disabled: true}}
        align={alignEnd ? 'end' : 'start'}
        width="medium"
      >
        <form
          onSubmit={e => {
            e.preventDefault()
            handleSubmit()
          }}
          className="m-3"
        >
          <div>
            <Text sx={{fontSize: 1, fontWeight: 'bold'}}>Request to dismiss alert</Text>
          </div>
          <div>
            <Text sx={{fontSize: '12px', color: 'fg.muted'}}>
              This alert needs approval before it can be dismissed.
            </Text>
          </div>
          <ActionList.Divider />
          <RadioGroup name="alertCloseReasonGroup" onChange={handleRadioGroupChange} required>
            <RadioGroup.Label>Dismissal reason</RadioGroup.Label>
            <FormControl>
              <Radio value={ResolutionType.Revoked} name="resolution" />
              <FormControl.Label>Revoked</FormControl.Label>
              <FormControl.Caption>{revokeText}</FormControl.Caption>
            </FormControl>
            <FormControl>
              <Radio value={ResolutionType.UsedInTests} name="resolution" />
              <FormControl.Label>Used in tests</FormControl.Label>
              <FormControl.Caption>{usedInTestsText}</FormControl.Caption>
            </FormControl>
            <FormControl>
              <Radio value={ResolutionType.FalsePositive} name="resolution" />
              <FormControl.Label>False positive</FormControl.Label>
              <FormControl.Caption>{falsePositiveText}</FormControl.Caption>
            </FormControl>
            <FormControl>
              <Radio value={ResolutionType.WontFix} name="resolution" />
              <FormControl.Label>Won&apos;t fix </FormControl.Label>
              <FormControl.Caption>{wontFixText}</FormControl.Caption>
            </FormControl>
            {reasonValidationError && (
              <>
                <ActionList.Divider />
                <RadioGroup.Validation variant="error">This field is required</RadioGroup.Validation>
              </>
            )}
          </RadioGroup>

          <Box sx={{display: 'grid', gap: 2, marginTop: 4}}>
            <FormControl>
              <FormControl.Label required>Comment</FormControl.Label>
              <Textarea
                sx={{width: '100%', display: 'block'}}
                placeholder="Add a comment"
                rows={2}
                ref={closureRequestCommentTextArea}
                maxLength={280}
                name="closure_request_comment"
              />
              {commentValidationError && (
                <FormControl.Validation variant="error">This field is required</FormControl.Validation>
              )}
            </FormControl>
            <Box sx={{display: 'inline-flex', mt: 1, ml: 'auto'}}>
              <Button
                sx={{mr: 2}}
                type="reset"
                onClick={() => {
                  hideActionsMenu()
                }}
              >
                Cancel
              </Button>
              <Button variant="primary" type="submit">
                Submit request
              </Button>
            </Box>
          </Box>
        </form>
      </AnchoredOverlay>
    </>
  )
}

try{ AlertClosureRequest.displayName ||= 'AlertClosureRequest' } catch {}